    private void badgesContent(LinearLayout r){section(r,"الأوسمة","تُفتح بالنقاط داخل كل مجال");String[] ds={"القرآن","الإنجليزية والقبول","العمل والدخل","الصحة","المعرفة والقراءة","التواصل","الأسرة","الانضباط"};for(String d:ds){int p=domainPoints(d),tier=badgeTier(p);LinearLayout c=card();c.setPadding(dp(12),dp(11),dp(12),dp(11));add(r,c,6);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);row.addView(new BadgeView(this,color(d),domainIcon(d),62),new LinearLayout.LayoutParams(dp(68),dp(68)));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(10),0,0,0);tx.addView(text(shortDomain(d),15,TEXT,true));tx.addView(text(badgeName(tier)+(tier<4?" • التالي عند "+ar(badgeNext(tier))+" نقطة":" • أعلى وسام"),11,MUTED,false));tx.addView(progress(p-badgeBase(tier),Math.max(1,badgeNext(tier)-badgeBase(tier)),color(d)));row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));c.addView(row);}}

