    private void storeContent(LinearLayout r){LinearLayout wallet=card();wallet.setPadding(dp(14),dp(13),dp(14),dp(13));add(r,wallet,8);LinearLayout w=new LinearLayout(this);w.setOrientation(LinearLayout.HORIZONTAL);w.setGravity(Gravity.CENTER_VERTICAL);w.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);LinearLayout wt=new LinearLayout(this);wt.setOrientation(LinearLayout.VERTICAL);wt.addView(text("رصيد المكافآت",13,MUTED,true));wt.addView(text(ar(credits())+" رصيد",25,GREEN,true));w.addView(wt,new LinearLayout.LayoutParams(0,-2,1));w.addView(circle("✦",50,Color.rgb(235,248,240),GREEN,23));wallet.addView(w);wallet.addView(text("هذا الرصيد منفصل عن نقاط التقدم؛ إنفاقه لا ينقص مستواك.",11,MUTED,false));section(r,"مكافآت مناسبة","وقت إضافي فوق راحتك المعتادة — لا تشتري النوم أو الراحة الأساسية");rewardItem(r,"🎮","٣٠ دقيقة لعبة/أنمي إضافية","فوق وقت الترفيه اليومي المعتاد.",15,"fun30",PURPLE);rewardItem(r,"🧭","٤٥ دقيقة استكشاف حر","اختر موضوعًا تحبه دون شعور بالذنب.",20,"explore45",TEAL);rewardItem(r,"⚽","جلسة هواية إضافية","كرة، شطرنج، لعبة قصصية أو مهارة تحبها.",25,"hobby",GREEN);rewardItem(r,"🌙","مساء خفيف","ألغِ المهام الإضافية فقط في مساء واحد.",35,"light_evening",BLUE);rewardItem(r,"🎬","٩٠ دقيقة ترفيه ممتد","تستخدمها في يوم مناسب ولا تزاحم النوم أو المسجد.",45,"fun90",ORANGE);rewardItem(r,"🌿","نصف يوم مرن","تحتفظ بالأساسيات فقط: المسجد، القرآن، النوم؛ والباقي راحة/خروج.",70,"half_flex",GREEN);}

