    private void compactTask(LinearLayout r,T t){LinearLayout c=card();c.setPadding(dp(10),dp(8),dp(10),dp(8));add(r,c,5);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);CheckBox cb=new CheckBox(this);cb.setChecked(done(t));cb.setButtonTintList(ColorStateList.valueOf(color(t.domain)));row.addView(cb,new LinearLayout.LayoutParams(dp(42),dp(45)));row.addView(circle(t.icon,38,soft(color(t.domain)),color(t.domain),16));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(9),0,dp(9),0);tx.addView(text(t.title,13,TEXT,true));tx.addView(text(time(t.start)+" • "+shortDomain(t.domain),10,MUTED,false));row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));c.addView(row);cb.setOnCheckedChangeListener((v,ch)->{setDone(t,ch);render();});}
    private void fullTask(LinearLayout r,T t){LinearLayout c=card();c.setPadding(dp(11),dp(9),dp(11),dp(9));add(r,c,6);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);CheckBox cb=new CheckBox(this);cb.setChecked(done(t));cb.setButtonTintList(ColorStateList.valueOf(color(t.domain)));row.addView(cb,new LinearLayout.LayoutParams(dp(44),dp(52)));row.addView(circle(t.icon,42,soft(color(t.domain)),color(t.domain),17));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(9),0,dp(9),0);tx.addView(text(t.title,14,TEXT,true));tx.addView(text(time(t.start)+" — "+time(t.end)+" • "+shortDomain(t.domain),10,MUTED,false));row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));if(t.points>0)row.addView(pill("+"+ar(t.points),color(t.domain),soft(color(t.domain))));c.addView(row);cb.setOnCheckedChangeListener((v,ch)->{setDone(t,ch);render();});}
    private void weekStrip(LinearLayout r){Calendar start=saturdayStart(Calendar.getInstance());LinearLayout strip=new LinearLayout(this);strip.setOrientation(LinearLayout.HORIZONTAL);strip.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);for(int i=0;i<7;i++){Calendar d=(Calendar)start.clone();d.add(Calendar.DAY_OF_MONTH,i);boolean now=dateKey(d).equals(todayKey);LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setGravity(Gravity.CENTER);x.setPadding(dp(4),dp(5),dp(4),dp(5));if(now)x.setBackground(round(GREEN,14));x.addView(center(new SimpleDateFormat("EEE",new Locale("ar")).format(d.getTime()).replace("،",""),9,now?WHITE:MUTED,false));x.addView(center(ar(d.get(Calendar.DAY_OF_MONTH)),13,now?WHITE:TEXT,true));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(57),1);lp.setMargins(dp(2),0,dp(2),0);strip.addView(x,lp);}add(r,strip,10);}
    private TextView chip(String s,boolean active){int c=filterColor(s);TextView t=center(s,11,active?WHITE:c,true);t.setPadding(dp(13),dp(7),dp(13),dp(7));t.setBackground(round(active?c:soft(c),15));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(35));lp.setMargins(dp(3),0,dp(3),0);t.setLayoutParams(lp);return t;}private int filterColor(String s){if(s.equals("قرآن"))return GREEN;if(s.equals("إنجليزية"))return BLUE;if(s.equals("عمل"))return ORANGE;if(s.equals("صحة"))return RED;if(s.equals("قراءة"))return PURPLE;if(s.equals("أسرة"))return PINK;return GREEN;}
    private LinearLayout segmented(){LinearLayout s=new LinearLayout(this);s.setOrientation(LinearLayout.HORIZONTAL);s.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);s.setPadding(dp(3),dp(3),dp(3),dp(3));s.setBackground(round(WHITE,18,BORDER));return s;}private TextView segment(String s,boolean active){TextView t=center(s,11,active?WHITE:NAVY,true);if(active)t.setBackground(round(GREEN,15));return t;}
    private View quick(String icon,String label,int c){LinearLayout x=card();x.setGravity(Gravity.CENTER);x.setPadding(dp(4),dp(9),dp(4),dp(9));x.addView(circle(icon,38,soft(c),c,16));x.addView(center(label,10,TEXT,true));return x;}
    private View bigRing(int pct,String label,int c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setGravity(Gravity.CENTER);x.addView(new Ring(this,pct,c),new LinearLayout.LayoutParams(dp(102),dp(102)));x.addView(center(label,11,MUTED,true));return x;}private View stat(String value,String label,int c){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(dp(8),dp(5),dp(8),dp(5));x.addView(text(value,18,c,true));x.addView(text(label,10,MUTED,false));return x;}private View metric(String icon,String value,String label,int c){LinearLayout x=card();x.setGravity(Gravity.CENTER);x.setPadding(dp(6),dp(10),dp(6),dp(10));x.addView(center(icon,18,c,true));x.addView(center(value,15,TEXT,true));x.addView(center(label,9,MUTED,false));return x;}
    private void domainRow(LinearLayout p,String d){int pts=domainPoints(d),tier=badgeTier(pts);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(0,dp(5),0,dp(5));LinearLayout h=new LinearLayout(this);h.setOrientation(LinearLayout.HORIZONTAL);h.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);h.addView(text(shortDomain(d),12,TEXT,true),new LinearLayout.LayoutParams(0,-2,1));h.addView(text(ar(pts)+" • "+badgeName(tier),10,color(d),true));row.addView(h);row.addView(progress(pts-badgeBase(tier),Math.max(1,badgeNext(tier)-badgeBase(tier)),color(d)));p.addView(row);}
    private void addMenu(LinearLayout r,String icon,String title,String sub,int c,Runnable run){LinearLayout x=card();x.setPadding(dp(12),dp(11),dp(12),dp(11));add(r,x,7);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(Gravity.CENTER_VERTICAL);row.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);row.addView(circle(icon,44,soft(c),c,18));LinearLayout tx=new LinearLayout(this);tx.setOrientation(LinearLayout.VERTICAL);tx.setPadding(dp(10),0,dp(10),0);tx.addView(text(title,14,TEXT,true));tx.addView(text(sub,10,MUTED,false));row.addView(tx,new LinearLayout.LayoutParams(0,-2,1));row.addView(text("‹",23,MUTED,false));x.addView(row);x.setOnClickListener(v->run.run());}

    private ScrollView scroll(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setBackgroundColor(BG);s.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);return s;}private LinearLayout root(ScrollView s){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(16),dp(15),dp(16),dp(28));r.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);s.addView(r);return r;}private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);c.setBackground(round(WHITE,19,BORDER));c.setElevation(dp(1));return c;}private void add(LinearLayout r,View v,int top){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(top),0,0);r.addView(v,lp);}private TextView text(String s,int size,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(c);t.setGravity(Gravity.RIGHT);t.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private TextView center(String s,int size,int c,boolean bold){TextView t=text(s,size,c,bold);t.setGravity(Gravity.CENTER);return t;}private TextView pill(String s,int c,int bg){TextView t=center(s,10,c,true);t.setPadding(dp(8),dp(4),dp(8),dp(4));t.setBackground(round(bg,18));return t;}private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(WHITE);b.setTextSize(11);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackground(round(c,14));return b;}private TextView circle(String s,int size,int bg,int fg,int textSize){TextView t=center(s,textSize,fg,true);t.setBackground(round(bg,999));t.setPadding(0,0,0,0);t.setLayoutParams(new LinearLayout.LayoutParams(dp(size),dp(size)));return t;}private ProgressBar progress(int val,int max,int c){ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(Math.max(1,max));p.setProgress(Math.max(0,Math.min(val,Math.max(1,max))));p.setProgressTintList(ColorStateList.valueOf(c));p.setProgressBackgroundTintList(ColorStateList.valueOf(Color.rgb(230,235,241)));p.setMinimumHeight(dp(6));return p;}private LinearLayout.LayoutParams weight(){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),0,dp(3),0);return lp;}private GradientDrawable round(int c,int rad){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(rad));return d;}private GradientDrawable round(int c,int rad,int stroke){GradientDrawable d=round(c,rad);d.setStroke(dp(1),stroke);return d;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private int pct(int v,int t){return t<=0?0:Math.max(0,Math.min(100,Math.round(v*100f/t)));}private String ar(int n){return String.valueOf(n).replace('0','٠').replace('1','١').replace('2','٢').replace('3','٣').replace('4','٤').replace('5','٥').replace('6','٦').replace('7','٧').replace('8','٨').replace('9','٩');}private String dateKey(Calendar c){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime());}private Calendar saturdayStart(Calendar c){Calendar x=(Calendar)c.clone();int diff=(x.get(Calendar.DAY_OF_WEEK)-Calendar.SATURDAY+7)%7;x.add(Calendar.DAY_OF_MONTH,-diff);return x;}private String time(int m){int h=(m/60)%24,mi=m%60;String ap=h<12?"ص":"م";int hh=h%12;if(hh==0)hh=12;return ar(hh)+":"+(mi<10?"٠":"")+ar(mi)+" "+ap;}

    class Ring extends View {Paint p=new Paint(1);int val,c;Ring(Activity a,int v,int color){super(a);val=v;c=color;}protected void onDraw(Canvas x){super.onDraw(x);float sw=dp(7),pad=sw+dp(2);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(sw);p.setStrokeCap(Paint.Cap.ROUND);p.setColor(Color.rgb(232,236,242));x.drawArc(new RectF(pad,pad,getWidth()-pad,getHeight()-pad),-90,360,false,p);p.setColor(c);x.drawArc(new RectF(pad,pad,getWidth()-pad,getHeight()-pad),-90,360*val/100f,false,p);p.setStyle(Paint.Style.FILL);p.setColor(TEXT);p.setTextAlign(Paint.Align.CENTER);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextSize(dp(17));x.drawText(ar(val)+"٪",getWidth()/2f,getHeight()/2f+dp(6),p);}}
    class BadgeView extends View {Paint p=new Paint(1);int c;String label;BadgeView(Activity a,int color,String s,int ignored){super(a);c=color;label=s;}protected void onDraw(Canvas x){super.onDraw(x);float w=getWidth(),h=getHeight(),cx=w/2f,cy=h/2f,r=Math.min(w,h)*.43f;Path q=new Path();for(int i=0;i<6;i++){double a=Math.toRadians(-90+i*60);float px=cx+(float)Math.cos(a)*r,py=cy+(float)Math.sin(a)*r;if(i==0)q.moveTo(px,py);else q.lineTo(px,py);}q.close();p.setStyle(Paint.Style.FILL);p.setColor(soft(c));x.drawPath(q,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setColor(c);x.drawPath(q,p);p.setStyle(Paint.Style.FILL);p.setColor(c);x.drawCircle(cx,cy,r*.62f,p);p.setColor(WHITE);p.setTypeface(Typeface.DEFAULT_BOLD);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(Math.min(w,h)*.25f);x.drawText(label,cx,cy+p.getTextSize()*.35f,p);}}
    class WeekBars extends View {Paint p=new Paint(1);WeekBars(Activity a){super(a);}protected void onDraw(Canvas x){super.onDraw(x);float left=dp(12),bottom=getHeight()-dp(28),top=dp(16),gap=dp(8),bw=(getWidth()-left*2-gap*5)/6f;Calendar c=saturdayStart(Calendar.getInstance());c.add(Calendar.DAY_OF_MONTH,-35);for(int i=0;i<6;i++){int po=0,ta=0;Calendar w=(Calendar)c.clone();for(int j=0;j<7;j++){po+=dayPoints(w);ta+=dayTarget(w);w.add(Calendar.DAY_OF_MONTH,1);}int v=pct(po,ta);float h=(bottom-top)*v/100f,l=left+i*(bw+gap);p.setColor(i==5?GREEN:Color.rgb(220,226,234));x.drawRoundRect(new RectF(l,bottom-h,l+bw,bottom),dp(5),dp(5),p);p.setColor(MUTED);p.setTextAlign(Paint.Align.CENTER);p.setTextSize(dp(9));x.drawText(ar(v)+"٪",l+bw/2,bottom-h-dp(5),p);x.drawText("أ"+ar(i+1),l+bw/2,getHeight()-dp(8),p);c.add(Calendar.DAY_OF_MONTH,7);}}}
    class Trend extends View {Paint p=new Paint(1);Path path=new Path();Trend(Activity a){super(a);}protected void onDraw(Canvas x){super.onDraw(x);float l=dp(12),r=getWidth()-dp(12),t=dp(18),b=getHeight()-dp(22);p.setStrokeWidth(dp(1));p.setColor(Color.rgb(232,236,241));for(int i=0;i<4;i++){float y=t+(b-t)*i/3f;x.drawLine(l,y,r,y,p);}Calendar c=Calendar.getInstance();c.add(Calendar.DAY_OF_MONTH,-29);path.reset();for(int i=0;i<30;i++){float xx=l+(r-l)*i/29f,yy=b-(b-t)*dayRate(c)/100f;if(i==0)path.moveTo(xx,yy);else path.lineTo(xx,yy);c.add(Calendar.DAY_OF_MONTH,1);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(3));p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);p.setColor(GREEN);x.drawPath(path,p);p.setStyle(Paint.Style.FILL);}}
